function icon(name, cls='') {return `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">${ICONS[name]||ICONS.sparkles}</svg>`;}
function mark(cls='') {return `<svg class="${cls}" viewBox="0 0 64 64" aria-hidden="true" fill="none"><path d="M8 51 30.6 10 56 51H43L30.6 29 21 51z" fill="currentColor"/><path d="M33 39h10l7 12H40z" fill="#e6cb87"/></svg>`;}
function esc(value=''){return String(value).replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));}
const money=n=>'Rp'+Number(n||0).toLocaleString('id-ID');
function save(key,val){try{localStorage.setItem(`arjuna_v2_${key}`,JSON.stringify(val))}catch(e){console.warn('Penyimpanan lokal tidak tersedia',e)}}
function load(key, fallback){try{let s=localStorage.getItem(`arjuna_v2_${key}`);return s?JSON.parse(s):fallback}catch{return fallback}}
const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
